# Matrix defects and synthesis: independent validator transcribes the displayed cells separately.
matrix_cases={
'P62I-OLI-L-001':('B/Y is the only pure equilibrium with total 10; A/X maximizes joint profit at 16','A/X is the only pure equilibrium with total 16; B/Y maximizes joint profit at 10','B/Y is the only pure equilibrium with total 10; A/Y maximizes joint profit at 14','A/X and B/Y are both pure equilibria and both have total 16'),
'P62I-OLI-L-004':('A/X and B/Y are pure equilibria; A/X has the larger joint total, 23 versus 21','B/Y is the only pure equilibrium because Column prefers its payoff there','A/X is the only pure equilibrium because it has the largest joint total','Neither diagonal cell is an equilibrium because the off-diagonal totals are lower'),
'P62I-OLI-L-010':('There is no pure-strategy equilibrium; all four cells tie at a joint total of 8','There are four pure-strategy equilibria because all four joint totals equal 8','A/X is the unique equilibrium because Row receives 6 there','B/Y is the joint optimum because Column receives 2 there')}
for id,ops in matrix_cases.items():
 put(id,'Refer to the payoff matrix for '+{'001':'a regional freight pricing review','004':'a port-services coordination review','010':'a rotating delivery-slot game'}[id[-3:]]+'. Payoffs are profits ordered (Row, Column). Comparing both players’ best responses with the sum of their payoffs, which conclusion is supported?',list(ops),
 {'001':'Row prefers B under either column and Column prefers Y under either row. Their unique pure equilibrium B/Y pays (5,5), total 10. Joint totals at A/X, A/Y, B/X, B/Y are 16,14,14,10, so A/X maximizes joint profit. Consumer surplus is absent, so this is not a demonstrated social optimum.',
 '004':'Against X, Row chooses A; against Y, Row chooses B. Against A, Column chooses X; against B, Column chooses Y. Both diagonal cells are equilibria, with joint totals 23 and 21. Neither player has a dominant strategy. The maximum joint-profit cell is also one equilibrium; it need not be the selected outcome.',
 '010':'Row chooses A against X and B against Y. Column chooses Y against A and X against B. Every pure cell permits a profitable deviation. Each cell totals 8, so equal joint profit does not create a pure equilibrium. A mixed-strategy equilibrium is distinct from a pure one.'}[id[-3:]],'F: Integrate all pure equilibria, best responses and joint totals without assuming a prisoner’s dilemma or total social welfare.')
for n in [2,5,8,11,14,17]:
 id=f'P62I-OLI-L-{n:03d}';old=qs[id]
 # Both contingencies, rather than a missing specified opponent action.
 data={'002':('B against X and B against Y','16 exceeds 12 against X; 7 exceeds 4 against Y'), '005':('B against X and B against Y','13 exceeds 9 against X; 6 exceeds 4 against Y'), '008':('A against X and B against Y','8 exceeds 6 against X; 5 exceeds 3 against Y'), '011':('B against X and B against Y','15 exceeds 12 against X; 6 exceeds 3 against Y'), '014':('B against X and B against Y','14 exceeds 10 against X; 7 exceeds 5 against Y'), '017':('A against X and B against Y','11 exceeds 2 against X; 7 exceeds 1 against Y')}
 correct,why=data[id[-3:]]; alternatives=['A against X and A against Y','A against X and B against Y','B against X and A against Y','B against X and B against Y']
